void main()
{
    u_xlat0 = _Time.yyyy * vec4(1.10000002, 1.70000005, 2.29999995, 1.89999998);
    u_xlat0.xz = in_POSITION0.xx * vec2(0.310000002, 0.449999988) + u_xlat0.xz;
    u_xlat0.yw = in_POSITION0.xx * vec2(0.829999983, 0.600000024) + (-u_xlat0.yw);
    u_xlat0 = sin(u_xlat0);
    u_xlat0.x = u_xlat0.x * 0.600000024;
    u_xlat4 = u_xlat0.z * 0.5 + 0.5;
    u_xlat0.x = u_xlat0.y * 0.400000006 + u_xlat0.x;
    u_xlat0.x = u_xlat0.x * _SwellAmp;
    u_xlat2 = in_POSITION0.y / _Height;
    u_xlat2 = clamp(u_xlat2, 0.0, 1.0);
    u_xlat0.x = u_xlat2 * u_xlat0.x + 1.0;
    vs_TEXCOORD1 = u_xlat2;
    u_xlat2 = in_TEXCOORD1.x * 0.349999994;
    u_xlat2 = u_xlat0.w * u_xlat2;
    u_xlat0.x = in_POSITION0.y * u_xlat0.x + (-u_xlat2);
    u_xlat1 = u_xlat0.xxxx * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat1 = hlslcc_mtx4x4unity_ObjectToWorld[0] * in_POSITION0.xxxx + u_xlat1;
    u_xlat0.x = in_TEXCOORD1.x * _LipWobble;
    u_xlat0.x = (-u_xlat0.x) * u_xlat4 + in_POSITION0.z;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat0.xyz = hlslcc_mtx4x4unity_ObjectToWorld[3].xyz * in_POSITION0.www + u_xlat0.xyz;
    vs_TEXCOORD4.xyz = (-u_xlat0.xyz) + _WorldSpaceCameraPos.xyz;
    u_xlat0 = u_xlat1.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat0 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat1.xxxx + u_xlat0;
    u_xlat0 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat1.zzzz + u_xlat0;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat1.wwww + u_xlat0;
    vs_TEXCOORD0.xy = in_TEXCOORD0.xy;
    vs_TEXCOORD2 = in_TEXCOORD1.x;
    u_xlat0.x = dot(in_NORMAL0.xyz, hlslcc_mtx4x4unity_WorldToObject[0].xyz);
    u_xlat0.y = dot(in_NORMAL0.xyz, hlslcc_mtx4x4unity_WorldToObject[1].xyz);
    u_xlat0.z = dot(in_NORMAL0.xyz, hlslcc_mtx4x4unity_WorldToObject[2].xyz);
    u_xlat6 = dot(u_xlat0.xyz, u_xlat0.xyz);
    u_xlat6 = inversesqrt(u_xlat6);
    vs_TEXCOORD3.xyz = vec3(u_xlat6) * u_xlat0.xyz;
    return;
}


#version 300 es

